    st.shared.f32 [%r35], %f76;
    add.u32 %r33, %r33, 1;
    setp.lt.u32 %p5, %r33, 256;
    @%p5 bra SUM_LOOP;
    mov.f32 %f77, 0f3F800000;
    div.rn.f32 %f78, %f77, %f74;      // 1/sum
    mov.u32 %r33, 0;
    shl.b32 %r36, %r0, 8;             // row*256 halves
    shl.b32 %r36, %r36, 1;            // row*512 bytes in psm
    add.u32 %r37, %r9, %r36;          // psm row byte base
NORM_LOOP:
    shl.b32 %r34, %r33, 2;
    add.u32 %r35, %r32, %r34;
    ld.shared.f32 %f76, [%r35];
    mul.f32 %f79, %f76, %f78;
    cvt.rn.f16.f32 %rh2, %f79;
    shl.b32 %r38, %r33, 1;
    add.u32 %r39, %r37, %r38;
    st.shared.b16 [%r39], %rh2;
    add.u32 %r33, %r33, 1;
    setp.lt.u32 %p6, %r33, 256;
    @%p6 bra NORM_LOOP;
SOFTMAX_DONE:
    bar.warp.sync 0xffffffff;
    // ---------------- pass 2: O = P V, output tiles are 16 rows x 16 dims ----------------
    mov.u32 %r14, 0;                  // output dim ntile 0..63
PV_N_LOOP:
    shl.b32 %r15, %r14, 4;            // n0 = dim tile*16
    mov.f32 %f64, 0f00000000;
    mov.f32 %f65, 0f00000000;
    mov.f32 %f66, 0f00000000;
    mov.f32 %f67, 0f00000000;
    mov.f32 %f68, 0f00000000;
    mov.f32 %f69, 0f00000000;
    mov.f32 %f70, 0f00000000;
    mov.f32 %f71, 0f00000000;
    mov.u32 %r16, 0;                  // key ktile 0..15
PV_K_LOOP:
    shl.b32 %r17, %r16, 4;            // k0 = key tile*16
    // stage transposed V tile: vtile[dim*16+key] = V[k0+key, n0+dim]
    mov.u32 %r18, 0;
ST_V_LOOP:
    add.u32 %r19, %r7, %r18;          // idx 0..255
    shr.u32 %r20, %r19, 4;            // key
    and.b32 %r21, %r19, 15;           // dim
    add.u32 %r24, %r17, %r20;         // global key
    shl.b32 %r24, %r24, 10;
    add.u32 %r24, %r24, %r4;
    add.u32 %r25, %r15, %r21;         // global dim
    add.u32 %r24, %r24, %r25;
    shl.b32 %r24, %r24, 1;
    cvt.u64.u32 %rd6, %r24;
    add.u64 %rd6, %rd6, %rd2;
    ld.global.b16 %rh3, [%rd6];
    shl.b32 %r22, %r21, 4;            // dim*16
    add.u32 %r22, %r22, %r20;         // dim*16+key
    shl.b32 %r23, %r22, 1;
    add.u32 %r26, %r12, %r23;
    st.shared.b16 [%r26], %rh3;
    add.u32 %r18, %r18, 1;
    setp.lt.u32 %p7, %r18, 8;
    @%p7 bra ST_V_LOOP;
    // A = P[0:16, k0:k0+16], row-major stride 256 halves
    shl.b32 %r27, %r17, 1;            // k0 halves -> bytes
    add.u32 %r28, %r9, %r27;
    bar.warp.sync 0xffffffff;
    // A fragment from psm; lane addresses select 16 rows and two k-halves
    and.b32 %r30, %r0, 15;
    shl.b32 %r30, %r30, 9;            // row*512 bytes
    shl.b32 %r27, %r17, 1;            // k0 halves -> bytes
    add.u32 %r30, %r30, %r27;
    shr.u32 %r31, %r0, 4;
    shl.b32 %r31, %r31, 4;
    add.u32 %r30, %r30, %r31;
    add.u32 %r30, %r30, %r9;
    ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%r32,%r33,%r34,%r35}, [%r30];
    // vtile is n-major with k contiguous, exactly the col-major B layout
    and.b32 %r30, %r0, 7;
    shr.u32 %r31, %r0, 4;
    shl.b32 %r31, %r31, 3;
    add.u32 %r30, %r30, %r31;
    shl.b32 %r30, %r30, 5;
    shr.u32 %r31, %r0, 3;
    and.b32 %r31, %r31, 1;
    shl.b32 %r31, %r31, 4;
    add.u32 %r30, %r30, %r31;
    add.u32 %r30, %r30, %r12;
    ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%r40,%r41,%r42,%r43}, [%r30];
    mma.sync.aligned.m16n8k16.row.col.f32.f16.f16.f32 {%f64,%f65,%f66,%f67}, {%r32,%r33,%r34,%r35}, {%r40,%r41}, {%f64,%f65,%f66,%f67};
