    cvt.rn.f16.f32 %rh9, %f81;
    cvt.rn.f16.f32 %rh10, %f82;
    cvt.rn.f16.f32 %rh11, %f83;
    cvt.rn.f16.f32 %rh12, %f84;
    cvt.rn.f16.f32 %rh13, %f85;
    cvt.rn.f16.f32 %rh14, %f86;
    cvt.rn.f16.f32 %rh15, %f87;
