import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Scaled dot-product attention specialized for the reference shapes:
//   Q, K, V : (2, 32, 256, 1024) fp16, contiguous
//   out = softmax(Q @ K^T * (1/sqrt(1024))) @ V
// grid = (sequence_length=256, batch*heads=64, 1), block = (256, 1, 1)
// Optimization: stage each query row and 16-key K tiles in shared memory,
// then map 16 consecutive threads to one key so the 1024-dim dot product is
// reduced by in-segment shuffles instead of a block reduction for every key.
.visible .entry attention_kernel(
    .param .u64 pQ,
    .param .u64 pK,
    .param .u64 pV,
    .param .u64 pO
)
{
    .reg .pred %p<12>;
    .reg .b16 %rh<16>;
    .reg .b32 %r<48>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<80>;
    .shared .align 16 .f32 qf[1024];
    .shared .align 16 .b16 ks[16384];
    .shared .align 4 .f32 scores[256];
    .shared .align 4 .f32 red[8];
    .shared .align 4 .f32 bcast[1];
    ld.param.u64 %rd0, [pQ];
    ld.param.u64 %rd1, [pK];
    ld.param.u64 %rd2, [pV];
    ld.param.u64 %rd3, [pO];
    mov.u32 %r0, %tid.x;        // tid   (0..255)
    mov.u32 %r1, %ctaid.x;      // query row index
    mov.u32 %r2, %ctaid.y;      // bh = batch*32 + head
    shl.b32 %r3, %r2, 8;        // bh*256
    add.u32 %r3, %r3, %r1;      // global row
    shl.b32 %r4, %r3, 10;       // qoff = row*1024 (elements)
    shl.b32 %r5, %r2, 18;       // kvbase = bh*262144 (elements)
    and.b32 %r6, %r0, 31;       // lane
    shr.u32 %r7, %r0, 5;        // warp id
    shl.b32 %r24, %r0, 2;       // 4*tid, retained for the value/output pass
    // ---- stage this block's query row into shared memory as f32 ----
    add.u32 %r8, %r4, %r24;
    shl.b32 %r8, %r8, 1;        // bytes
    cvt.u64.u32 %rd4, %r8;
    add.u64 %rd4, %rd4, %rd0;
    ld.global.v2.b32 {%r22, %r23}, [%rd4];
    mov.b32 {%rh0, %rh1}, %r22;
    mov.b32 {%rh2, %rh3}, %r23;
